/**
 * Whaleal Cart Features 功能介绍
 * 多语言：卡片内容来自 i18n/dictionaries/products.js（与英文版逐条对应）
 * @author 恒哥
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import { usePageI18n } from '../i18n';
import productsCopy from '../i18n/dictionaries/products';
import './page.css';

export default function WhalealCartFeatures({ pageContext }) {
  const { locale, localePath, page } = usePageI18n(pageContext);
  const c = productsCopy[locale] || productsCopy.en;
  // SEO 走 pages.js（多语言）—— 见 index.js 的说明
  const meta = page.products;

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title={meta.metaTitle}
        description={meta.metaDescription}
        pathname="/products"
        hrefLang={locale}
      />
      <div className="page-container products-page">
        <div className="page-header products-header">
          <h1>{c.pageTitle}</h1>
          <p>{c.pageLead}</p>
        </div>

        <div className="products-grid">
          {c.cards.map((card) => (
            <div className="product-card" key={card.title}>
              <h2>
                {card.title} {card.tier ? <span className="product-card-tier">{card.tier}</span> : null}
              </h2>
              <p>{card.lead}</p>
              <ul>
                {card.bullets.map((b) => (
                  <li key={b} dangerouslySetInnerHTML={{ __html: b }} />
                ))}
              </ul>
            </div>
          ))}
        </div>

        <div className="about-actions" style={{ marginTop: '40px', textAlign: 'center' }}>
          <Link to={localePath('/help/')} className="about-link" style={{ marginRight: '20px' }}>
            {c.helpLink}
          </Link>
          <Link to={localePath('/install/')} className="about-link">
            {c.installLink}
          </Link>
        </div>
      </div>
    </Layout>
  );
}